#include <vector>
using namespace std;

class Solution {
public:
    bool check(vector<int>& nums) {
        int drops = 0;
        int n = nums.size();
        for (int i = 0; i < n; ++i) {
            if (nums[i] > nums[(i + 1) % n]) {
                drops++;
                if (drops > 1) return false;
            }
        }
        return true;
    }
};

class Solution {
    public boolean check(int[] nums) {
        int drops = 0;
        int n = nums.length;
        for (int i = 0; i < n; ++i) {
            if (nums[i] > nums[(i + 1) % n]) {
                drops++;
                if (drops > 1) return false;
            }
        }
        return true;
    }
}

